// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0) && target != address(this) && uint160(target) > 100);
        value = bound(value, 1, 1 ether);

        // owner of c is address(this) (msg.sender at deployment)
        vm.deal(address(c), 2 * value);
        uint256 before = address(c).balance;

        vm.prank(address(this));
        bool ok;
        try c.sendMoney(target, value) { ok = true; } catch { ok = false; }

        assertTrue(ok && address(c).balance == before - value);
    }
}
